import json, re, sys

ALLOWED = set('+-×÷⌈⌊*⍳⍴,⌽⍉/⊂≡≢⍋⍒↑↓⍷∊~∪∩')
NEUTRAL = set('0123456789¯. \t←()[];abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_')

def strip_comments(s):
    out=[]
    for line in s.split('\n'):
        inq=False; res=''
        for ch in line:
            if ch=="'": inq = not inq; res+=ch; continue
            if ch=='⍝' and not inq: break
            res+=ch
        out.append(res)
    return '\n'.join(out)

def classify(expr):
    e = strip_comments(expr)
    reasons=[]
    # character literals
    if "'" in e: reasons.append('characters')
    # strip string literals for glyph scan
    e2 = re.sub(r"'[^']*'", '', e)
    if '⎕' in e2 or '⍞' in e2: reasons.append('⎕ system name')
    if re.search(r'^\s*\]', e2, re.M): reasons.append('] user command')
    if '{' in e2: reasons.append('dfn')
    extra = sorted({ch for ch in e2 if ch not in ALLOWED and ch not in NEUTRAL
                    and ch not in '⎕⍞{}]' and not ch.isspace()})
    if extra: reasons.append('glyphs outside the set: ' + ' '.join(extra))
    return reasons

for f in sys.argv[1:]:
    cells=json.load(open(f))
    for c in cells:
        c['reasons']=classify(c['input'])
    json.dump(cells, open(f,'w'), indent=1, ensure_ascii=False)
    core=[c['n'] for c in cells if not c['reasons']]
    print('==',f,'total',len(cells),'auto-core',len(core),core)
    for c in cells:
        if c['reasons']:
            print('  %3d %-42s  %s'%(c['n'], c['input'].split('\n')[0][:42], '; '.join(c['reasons'])))
PYEOF
